 "content": "from collections import Counter


def _row_pattern(row, start=3):
    """Find the shortest horizontal period explaining the visible lattice."""
    known = [(c, v) for c, v in enumerate(row) if c >= start and v != 0]
    if not known:
        return {}
    fits = []
    for p in range(2, 13):
        counts = [Counter() for _ in range(p)]
        for c, v in known:
            counts[c % p][v] += 1
        mapping = {i: ct.most_common(1)[0][0] for i, ct in enumerate(counts) if ct}
        errors = sum(1 for c, v in known if mapping[c % p] != v)
        fits.append((errors, p, mapping))
    best_errors = min(x[0] for x in fits)
    # Ignore at most two exceptional seed cells (present in these lattices),
    # preferring the simplest repeat that otherwise matches the observations.
    acceptable = [x for x in fits if x[0] <= best_errors + 2]
    return min(acceptable, key=lambda x: x[1])[2]


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for r in range(h):
        pattern = _row_pattern(grid[r])
        for c in range(w):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = pattern.get(c % max(1, len(pattern)), 1)
    return out
